## Multi index tracking example[#](https://numpy.org/doc/stable/reference/c-api/iterator.html#multi-index-tracking-example "Link to this heading")
This example shows you how to work with the [`NPY_ITER_MULTI_INDEX`](https://numpy.org/doc/stable/reference/c-api/iterator.html#c.NPY_ITER_MULTI_INDEX "NPY_ITER_MULTI_INDEX") flag. For simplicity, we assume the argument is a two-dimensional array.
```
intPrintMultiIndex(PyArrayObject*arr){
NpyIter*iter;
NpyIter_IterNextFunc*iternext;
npy_intpmulti_index[2];

iter=NpyIter_New(
arr,NPY_ITER_READONLY|NPY_ITER_MULTI_INDEX|NPY_ITER_REFS_OK,
NPY_KEEPORDER,NPY_NO_CASTING,NULL);
if(iter==NULL){
return-1;
}
if(NpyIter_GetNDim(iter)!=2){
NpyIter_Deallocate(iter);
PyErr_SetString(PyExc_ValueError,"Array must be 2-D");
return-1;
}
if(NpyIter_GetIterSize(iter)!=0){
iternext=NpyIter_GetIterNext(iter,NULL);
if(iternext==NULL){
NpyIter_Deallocate(iter);
return-1;
}
NpyIter_GetMultiIndexFunc*get_multi_index=
NpyIter_GetGetMultiIndex(iter,NULL);
if(get_multi_index==NULL){
NpyIter_Deallocate(iter);
return-1;
}

do{
get_multi_index(iter,multi_index);
printf("multi_index is [%"NPY_INTP_FMT", %"NPY_INTP_FMT"]\n",
multi_index[0],multi_index[1]);
}while(iternext(iter));
}
if(!NpyIter_Deallocate(iter)){
return-1;
}
return0;
}

